function applyImportedDemoCSV(store){
  const own='demo-user';
  const crm=importedDemoCSV.CRM_100_DEMO.map(r=>({...r,crm_id:r.id,phone:'',altphone:'',userid:own,assigned_user_id:own}));
  store.crm=crm;
  const byId=new Map(crm.map(r=>[r.id,r]));
  const asClient=r=>byId.get(r.demo_client_id)||{};
  store.preview_inventory=crm.map((r,i)=>{const rec=importedDemoCSV.Websites.find(w=>w.demo_client_id===r.id);return {id:'demo-preview-'+i,crm_id:r.id,sitekey:r.sitekey||('demo-'+i),previewurl:rec?.previewurl||'https://demo.example.com/previews/'+encodeURIComponent(r.company||r.id),url:rec?.previewurl||'https://demo.example.com/previews/'+encodeURIComponent(r.company||r.id),liveurl:rec?.liveurl||'',status:rec?.status||'Preview ready',company:r.company};});
  store.site_keys=importedDemoCSV.Websites.map((r,i)=>({id:'demo-site-'+i,crm_id:r.demo_client_id,sitekey:r.sitekey,previewurl:r.previewurl,company:r.company}));
  store.outreach_tasks=importedDemoCSV.Tasks.map((r,i)=>({id:'demo-task-'+i,crm_id:r.demo_client_id,user_id:own,owner_id:own,title:r.task_title,description:r.instructions,priority:r.priority,status:r.status,due_at:r.due_at,company_name:r.company,created_at:new Date().toISOString()}));
  store.sh_sales_opportunities=importedDemoCSV.Opportunities.map((r,i)=>({id:'demo-opportunity-'+i,crm_id:r.demo_client_id,company_name:r.company,company:r.company,stage:r.stage,status:r.stage,amount_cents:Number(r.expected_value_cents||0),expected_value_cents:Number(r.expected_value_cents||0),hosting_plan:r.hosting_plan,preview_url:r.preview_url,next_step:r.next_step,follow_up_at:r.follow_up_at,user_id:own,salesperson_user_id:own,created_at:new Date().toISOString()}));
  store.outreach_sales=importedDemoCSV.Sales_Progress.map((r,i)=>({id:'demo-sale-'+i,crm_id:r.demo_client_id,company_name:r.company,company:r.company,user_id:own,salesperson_user_id:own,status:r.fulfillment||r.development_payment||'registered',registration:r.registration,agreement:r.agreement,development_payment:r.development_payment,hosting:r.hosting,fulfillment:r.fulfillment,commission_cents:Number(r.commission_cents||0),amount_cents:Number(r.real_revenue_cents||0),created_at:new Date().toISOString()}));
  store.callcenter_commissions=importedDemoCSV.Sales_Progress.map((r,i)=>({id:'demo-commission-'+i,crm_id:r.demo_client_id,company_name:r.company,user_id:own,amount_cents:Number(r.commission_cents||0),amount:Number(r.commission_cents||0)/100,status:['waiting','pending','complete'][i%3],created_at:new Date().toISOString()}));
  store.callcenter_call_activity=importedDemoCSV.Calls_Transcripts.map((r,i)=>({id:r.call_id||'demo-call-'+i,crm_id:r.demo_client_id,company:r.company,user_id:own,caller_user_id:own,called_at:r.called_at,created_at:r.called_at,duration_seconds:Number(r.duration_seconds||0),outcome:r.outcome,notes:r.notes,demo:true}));
  store.callcenter_transcripts=importedDemoCSV.Calls_Transcripts.map((r,i)=>({id:'demo-transcript-'+i,call_id:r.call_id,crm_id:r.demo_client_id,user_id:own,transcript:r.transcript_excerpt,text:r.transcript_excerpt,created_at:r.called_at,demo:true}));
  store.outreach_sale_events=importedDemoCSV.Activity.map((r,i)=>({id:'demo-event-'+i,crm_id:r.demo_client_id,company:r.company,user_id:own,event_type:r.activity_type,status:r.activity_status,notes:r.notes,created_at:r.recorded_at}));
  store.callcenter_call_feedback=importedDemoCSV.Calls_Transcripts.map((r,i)=>({id:'demo-feedback-'+i,crm_id:r.demo_client_id,user_id:own,outcome:r.outcome,notes:r.notes,created_at:r.called_at}));
  store.demo_agreements=importedDemoCSV.Agreements;
  store.demo_payments=importedDemoCSV.Payments_SIMULATED;
  store.callcenter_profiles=[{...(store.callcenter_profiles?.[0]||{}),id:'demo-profile',user_id:own,display_name:'Demo User',onboarding_completed:true,commission_acknowledged:true,last_call_at:new Date().toISOString(),created_at:new Date().toISOString(),disabled_at:null,active:true}];
  store._fictionalCSVVersion=3;
  return store;
}

// Fictional sales distribution (100 unique CRM clients, 36 confirmed sales).
function populateDemoSales(store){
  const crm=(store.crm||[]).slice(0,100);
  if(crm.length!==100)return;
  const now=Date.now(), own='demo-user';
  const time=(days)=>new Date(now-days*86400000).toISOString();
  const stages=[...Array(12).fill('contacted'),...Array(12).fill('interested'),...Array(12).fill('registration_sent'),...Array(10).fill('registration'),...Array(9).fill('agreement'),...Array(9).fill('payment'),...Array(36).fill('confirmed')];
  store.sh_sales_opportunities=[];
  store.outreach_sales=[];
  store.callcenter_commissions=[];
  crm.forEach((lead,i)=>{
    const stage=stages[i], days=(i*3)%38, at=time(days), name=lead.company||lead.name||'Demo Business';
    if(['contacted','interested','registration_sent'].includes(stage)){
      store.sh_sales_opportunities.push({id:'demo-opportunity-'+i,crm_id:lead.id,company_name:name,customer_email:lead.email||'',salesperson_user_id:own,user_id:own,stage,status:stage,hosting_plan:'',preview_url:'demo-preview.html',notes:'Fictional demo opportunity',created_at:at,updated_at:at});
    }else{
      const registered_at=at, agreement_at=['agreement','payment','confirmed'].includes(stage)?at:null;
      const payment_at=['payment','confirmed'].includes(stage)?at:null;
      const hosting_at=['payment','confirmed'].includes(stage)?at:null;
      const confirmed_at=stage==='confirmed'?at:null;
      store.outreach_sales.push({id:'demo-sale-'+i,crm_id:lead.id,company_name:name,client_name:name,salesperson_user_id:own,user_id:own,status:stage==='confirmed'?'confirmed':'registered',hosting_plan:i%3===0?'backend':'standard',registered_at,agreement_at,payment_at,hosting_at,launch_at:confirmed_at,confirmed_at,created_at:at,updated_at:at});
      if(stage==='confirmed'){
        const status=i%9===0?'waiting_client_payment':i%4===0?'pending':'complete';
        store.callcenter_commissions.push({id:'demo-commission-'+i,crm_id:lead.id,sale_id:'demo-sale-'+i,user_id:own,client_name:name,company_name:name,status,commission_amount_cents:3000,sale_amount_cents:10000,amount_cents:3000,amount:30,created_at:at,updated_at:at});
      }
    }
  });
  store._demoSalesVersion=4;
}
let db;try{db=JSON.parse(localStorage.getItem(key))||make()}catch{db=make()} if(!db.crm?.length)db=make();
if(db._fictionalCSVVersion!==3)applyImportedDemoCSV(db);
if(db._demoSalesVersion!==4)populateDemoSales(db);
function save(){try{localStorage.setItem(key,JSON.stringify(db))}catch(e){console.warn('Demo storage unavailable',e)}}save();
window.SteadyHandsDemo={data:db,reset(){localStorage.removeItem(key);location.reload()},save};
const blank=()=>({data:null,error:null});
function query(name){const state={name,select:'*',filters:[],orders:[],start:0,end:null,limit:null,single:false,head:false,count:false,operation:'select',payload:null};const chain={};
const add=(op,...args)=>{state.filters.push([op,...args]);return chain};
for(const m of ['eq','neq','gt','gte','lt','lte','like','ilike','in','is','contains','overlaps','match'])chain[m]=(...args)=>add(m,...args);
chain.not=(field,op,val)=>add('not',field,op,val);chain.or=()=>chain;chain.filter=(...args)=>add(...args);
chain.select=(columns='*',opts={})=>{state.select=columns;state.head=!!opts.head;state.count=!!opts.count;return chain};
chain.order=(field,opt={})=>{state.orders.push([field,opt]);return chain};chain.range=(start,end)=>{state.start=start;state.end=end;return chain};chain.limit=n=>{state.limit=n;return chain};chain.single=()=>{state.single=true;return chain};chain.maybeSingle=chain.single;
chain.insert=(payload)=>{state.operation='insert';state.payload=payload;return chain};chain.update=(payload)=>{state.operation='update';state.payload=payload;return chain};chain.upsert=(payload)=>{state.operation='upsert';state.payload=payload;return chain};chain.delete=()=>{state.operation='delete';return chain};
function matches(r){return state.filters.every(([op,k,v,x])=>{let a=r[k]; if(op==='eq')return String(a)===String(v);if(op==='neq')return String(a)!==String(v);if(op==='in')return (v||[]).map(String).includes(String(a));if(op==='is')return v===null?a==null:a===v;if(op==='not')return v===null?a!=null:String(a)!==String(v);if(op==='gt')return a>v;if(op==='gte')return a>=v;if(op==='lt')return a<v;if(op==='lte')return a<=v;if(op==='ilike'||op==='like')return String(a||'').toLowerCase().includes(String(v||'').replace(/%/g,'').toLowerCase());if(op==='contains')return Array.isArray(a)&&v.every(t=>a.includes(t));return true})}
function execute(){const rows=db[name]||(db[name]=[]);let found=rows.filter(matches);const count=found.length;if(state.operation==='delete'){db[name]=rows.filter(r=>!matches(r));save();return {data:state.single?found[0]||null:found,error:null,count}}if(state.operation==='update'){found.forEach(r=>Object.assign(r,state.payload||{}, {updated_at:new Date().toISOString()}));save()}if(state.operation==='insert'||state.operation==='upsert'){const input=Array.isArray(state.payload)?state.payload:[state.payload];found=input.map(x=>{const row={id:x?.id||'demo-'+Math.random().toString(36).slice(2),created_at:new Date().toISOString(),...x};if(state.operation==='upsert'){const prior=rows.find(r=>r.id===row.id);if(prior){Object.assign(prior,row);return prior}}rows.push(row);return row});save()}
for(const [field,opt] of state.orders)found.sort((a,b)=>{const cmp=String(a[field]??'').localeCompare(String(b[field]??''),undefined,{numeric:true});return opt.ascending===false?-cmp:cmp});found=found.slice(state.start,state.end===null?undefined:state.end+1);if(state.limit!==null)found=found.slice(0,state.limit);if(state.head)return{data:null,count,error:null};return{data:state.single?(found[0]||null):found,error:null,count:state.count?count:null}}
chain.then=(resolve,reject)=>Promise.resolve().then(execute).then(resolve,reject);return chain}
